    Differential Revision: https://phabricator.services.mozilla.com/D247196

diff --git a/mailnews/base/public/nsIMsgFolder.idl b/mailnews/base/public/nsIMsgFolder.idl
index 2b6fd9e1493..68d84ec3667 100644
--- a/mailnews/base/public/nsIMsgFolder.idl
+++ b/mailnews/base/public/nsIMsgFolder.idl
@@ -649,7 +649,14 @@ interface nsIMsgFolder : nsISupports {
   void alertFilterChanged(in nsIMsgWindow msgWindow);
   void throwAlertMsg(in string msgName, in nsIMsgWindow msgWindow);
   AString getStringWithFolderNameFromBundle(in string msgName);
+
+  /**
+   * These should not really be part of the public interface - they are
+   * implementation details used by the compaction code.
+   */
+  void notifyAboutToCompact();
   void notifyCompactCompleted();
+
   /**
    * Calculate ordering of this folder against another.
    */
diff --git a/mailnews/base/src/FolderCompactor.cpp b/mailnews/base/src/FolderCompactor.cpp
index 39f30416195..0826fd5368b 100644
--- a/mailnews/base/src/FolderCompactor.cpp
+++ b/mailnews/base/src/FolderCompactor.cpp
@@ -308,6 +308,7 @@ nsresult FolderCompactor::BeginCompacting(
   if (notifier) {
     notifier->NotifyFolderCompactStart(mFolder);
   }
+  mFolder->NotifyAboutToCompact();

   guardSemaphore.release();
   return NS_OK;
